def transform(grid):
    """Repeat the encoded full-width row colors by source-row index modulo count."""
    h, w = len(grid), len(grid[0])
    stripes = [(r, row[0]) for r, row in enumerate(grid)
               if row[0] != 0 and all(v == row[0] for v in row)]
    if not stripes:
        return [row[:] for row in grid]
    period = len(stripes)
    pattern = {}
    for r, color in stripes:
        residue = r % period
        if residue in pattern and pattern[residue] != color:
            raise ValueError("source stripe rows conflict under inferred period")
        pattern[residue] = color
    return [[pattern[r % period]] * w for r in range(h)]


